-- 데이터베이스 세트 366. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_sql_select_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 366, 'SQL 조회 손연습: WHERE·ORDER BY·LIMIT, 집계, GROUP BY·HAVING, JOIN·LEFT JOIN', '작은 가게(shop) 데이터베이스에서 SELECT 를 직접 쳐 봅니다. 조건으로 거르고, 정렬하고 개수를 줄이고, 범위로 찾고, COUNT·SUM 으로 집계하고, GROUP BY 와 HAVING 으로 묶어 거르고, JOIN 과 LEFT JOIN 으로 테이블을 합칩니다. 채점은 저장한 결과를 같은 쿼리를 실제로 실행한 결과와 비교합니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 366);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 1, '조건으로 거르기 (WHERE)', '`customers` 에서 도시(`city`)가 `Seoul` 인 고객의 `name` 과 `city` 두 컬럼을 조회해 그 출력을 **`/tmp/q1.txt`** 에 저장하세요. (`mariadb shop -e` 의 기본 출력 그대로 저장합니다.)', '`SELECT 컬럼 FROM 테이블 WHERE 조건;` 형태입니다. 문자열은 작은따옴표로 감싸요. 쉘의 따옴표와 겹치지 않게 바깥을 큰따옴표나 작은따옴표 중 하나로 정하세요.', 'mariadb shop -e "SELECT name, city FROM customers WHERE city = ''Seoul''" > /tmp/q1.txt
cat /tmp/q1.txt

# WHERE 조건에 맞는 행만 남긴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q1.txt ] && [ \\"$(sort /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, city FROM customers WHERE city = ''Seoul''\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q1.txt 가 Seoul 고객의 name, city 조회 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q1.txt ] && [ \\"$(sort /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, city FROM customers WHERE city = ''Seoul''\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 2, '정렬하고 개수 줄이기 (ORDER BY, LIMIT)', '`products` 에서 가장 **비싼 상품 3개** 의 `name` 과 `price` 를 **비싼 순서대로** 조회해 **`/tmp/q2.txt`** 에 저장하세요.', '`ORDER BY 컬럼 DESC` 는 큰 값부터 정렬하고, `LIMIT 숫자` 는 위에서부터 그 개수만 남깁니다. 정렬이 먼저, LIMIT 이 나중에 적용됩니다.', 'mariadb shop -e ''SELECT name, price FROM products ORDER BY price DESC LIMIT 3;'' > /tmp/q2.txt
cat /tmp/q2.txt

# 큰 값부터 정렬한 뒤 위 3개만', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, price FROM products ORDER BY price DESC LIMIT 3\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 비싼 순 상위 3개 조회 결과와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT name, price FROM products ORDER BY price DESC LIMIT 3\\")\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 3, '범위로 거르기 (BETWEEN)', '`products` 에서 가격(`price`)이 **3000 이상 40000 이하** 인 상품의 `name` 만 조회해 **`/tmp/q3.txt`** 에 저장하세요. 양 끝 값도 포함합니다.', '범위 조건은 `컬럼 BETWEEN 작은값 AND 큰값` 으로 쓸 수 있고, 양 끝 값이 포함됩니다. `>=` 와 `<=` 를 `AND` 로 이어도 같습니다.', 'mariadb shop -e ''SELECT name FROM products WHERE price BETWEEN 3000 AND 40000;'' > /tmp/q3.txt
cat /tmp/q3.txt

# BETWEEN 은 양 끝을 포함한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM products WHERE price BETWEEN 3000 AND 40000\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q3.txt 가 3000~40000 상품 이름 조회 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ] && [ \\"$(sort /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT name FROM products WHERE price BETWEEN 3000 AND 40000\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 4, '집계하기 (COUNT, SUM)', '`orders` 전체의 **주문 건수** 와 **수량 합계** 를 한 줄로 조회해 **`/tmp/q4.txt`** 에 저장하세요. 컬럼 이름(별칭)은 건수 `orders_cnt`, 합계 `total_qty` 로 하세요.', '`COUNT(*)` 는 행 수, `SUM(컬럼)` 은 합계입니다. 결과 컬럼에 이름을 붙이려면 `표현식 AS 이름` 처럼 씁니다.', 'mariadb shop -e ''SELECT COUNT(*) AS orders_cnt, SUM(qty) AS total_qty FROM orders;'' > /tmp/q4.txt
cat /tmp/q4.txt

# COUNT(*) 는 행 수, SUM 은 합계, AS 는 결과 컬럼 이름', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q4.txt ] && [ \\"$(cat /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT COUNT(*) AS orders_cnt, SUM(qty) AS total_qty FROM orders\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 가 orders_cnt, total_qty 집계 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q4.txt ] && [ \\"$(cat /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT COUNT(*) AS orders_cnt, SUM(qty) AS total_qty FROM orders\\")\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 5, '묶어서 세기 (GROUP BY)', '`customers` 를 도시(`city`)별로 묶어 도시와 **고객 수** 를 조회해 **`/tmp/q5.txt`** 에 저장하세요. 고객 수 컬럼의 이름(별칭)은 `cnt` 로 하세요.', '`GROUP BY 컬럼` 은 같은 값끼리 묶고, 집계 함수는 묶음마다 계산됩니다.', 'mariadb shop -e ''SELECT city, COUNT(*) AS cnt FROM customers GROUP BY city;'' > /tmp/q5.txt
cat /tmp/q5.txt

# GROUP BY 로 묶으면 집계가 묶음마다 계산된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q5.txt ] && [ \\"$(sort /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"SELECT city, COUNT(*) AS cnt FROM customers GROUP BY city\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q5.txt 가 도시별 고객 수 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q5.txt ] && [ \\"$(sort /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"SELECT city, COUNT(*) AS cnt FROM customers GROUP BY city\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 6, '묶음을 거르기 (HAVING)', '`orders` 를 고객(`customer_id`)별로 묶어 **주문이 2건 이상인** 고객의 `customer_id` 와 건수(`cnt`)를 조회해 **`/tmp/q6.txt`** 에 저장하세요.', '묶기 전의 행을 거르는 것은 `WHERE`, **묶은 뒤의 결과**(집계값)를 거르는 것은 `HAVING` 입니다.', 'mariadb shop -e ''SELECT customer_id, COUNT(*) AS cnt FROM orders GROUP BY customer_id HAVING COUNT(*) >= 2;'' > /tmp/q6.txt
cat /tmp/q6.txt

# WHERE 는 묶기 전 행, HAVING 은 묶은 뒤 집계 결과를 거른다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT customer_id, COUNT(*) AS cnt FROM orders GROUP BY customer_id HAVING COUNT(*) >= 2\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q6.txt 가 주문 2건 이상 고객 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ] && [ \\"$(sort /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT customer_id, COUNT(*) AS cnt FROM orders GROUP BY customer_id HAVING COUNT(*) >= 2\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 7, '두 테이블 합치기 (JOIN)', '고객 이름과 그 고객의 주문 번호를 함께 보려고 합니다. `customers` 와 `orders` 를 합쳐 `name` 과 주문 번호(`orders.id`, 별칭 `order_id`)를 조회해 **`/tmp/q7.txt`** 에 저장하세요.', '두 테이블을 이을 열은 `orders.customer_id = customers.id` 입니다. `JOIN ... ON 조건` 으로 잇고, 테이블에 짧은 별칭(`c`, `o`)을 붙이면 편합니다.', 'mariadb shop -e ''SELECT c.name, o.id AS order_id FROM customers c JOIN orders o ON o.customer_id = c.id;'' > /tmp/q7.txt
cat /tmp/q7.txt

# JOIN ... ON 으로 같은 값을 가진 행끼리 잇는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q7.txt ] && [ \\"$(sort /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, o.id AS order_id FROM customers c JOIN orders o ON o.customer_id = c.id\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q7.txt 가 고객 이름과 주문 번호 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q7.txt ] && [ \\"$(sort /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, o.id AS order_id FROM customers c JOIN orders o ON o.customer_id = c.id\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 7);

