SELECT 366, 8, '짝이 없는 행 찾기 (LEFT JOIN)', '한 번도 **주문하지 않은** 고객의 `name` 을 조회해 **`/tmp/q8.txt`** 에 저장하세요.', '`LEFT JOIN` 은 왼쪽 테이블의 행을 모두 남기고, 짝이 없으면 오른쪽 컬럼이 NULL 로 채워집니다. NULL 인지 확인할 때는 `IS NULL` 을 씁니다.', 'mariadb shop -e ''SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;'' > /tmp/q8.txt
cat /tmp/q8.txt

# LEFT JOIN 후 오른쪽이 NULL 인 행이 짝 없는 행이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q8.txt ] && [ \\"$(sort /tmp/q8.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q8.txt 가 주문 없는 고객 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q8.txt ] && [ \\"$(sort /tmp/q8.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 9, '세 테이블 합쳐 합계 내기', '고객별 **총 주문 금액**(수량 × 가격의 합)을 보려고 합니다. `customers`, `orders`, `products` 를 합쳐 고객 `name` 과 총액(`total`)을 조회해 **`/tmp/q9.txt`** 에 저장하세요. 주문이 없는 고객은 나오지 않아도 됩니다.', '`JOIN` 을 두 번 이어 쓸 수 있습니다. `orders.product_id = products.id` 로 가격을 붙인 뒤 `SUM(o.qty * p.price)` 를 고객별로 묶어 계산하세요.', 'mariadb shop -e ''SELECT c.name, SUM(o.qty * p.price) AS total FROM customers c JOIN orders o ON o.customer_id = c.id JOIN products p ON p.id = o.product_id GROUP BY c.name;'' > /tmp/q9.txt
cat /tmp/q9.txt

# JOIN 을 이어 붙이고 GROUP BY 로 고객별 합계를 낸다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, city VARCHAR(20));\\nINSERT INTO customers VALUES (1,\\"kim\\",\\"Seoul\\"),(2,\\"lee\\",\\"Busan\\"),(3,\\"park\\",\\"Seoul\\"),(4,\\"choi\\",\\"Daegu\\"),(5,\\"jung\\",\\"Busan\\"),(6,\\"han\\",\\"Seoul\\");\\nCREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT NOT NULL, category VARCHAR(20));\\nINSERT INTO products VALUES (1,\\"pen\\",1000,\\"stationery\\"),(2,\\"notebook\\",3000,\\"stationery\\"),(3,\\"mouse\\",15000,\\"electronics\\"),(4,\\"keyboard\\",40000,\\"electronics\\"),(5,\\"monitor\\",200000,\\"electronics\\");\\nCREATE TABLE orders (id INT PRIMARY KEY, customer_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL);\\nINSERT INTO orders VALUES (1,1,1,10),(2,1,3,1),(3,2,2,5),(4,3,4,1),(5,3,1,3),(6,3,5,1),(7,4,3,2),(8,5,2,4),(9,2,1,6),(10,5,4,1);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q9.txt ] && [ \\"$(sort /tmp/q9.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, SUM(o.qty * p.price) AS total FROM customers c JOIN orders o ON o.customer_id = c.id JOIN products p ON p.id = o.product_id GROUP BY c.name\\" | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 가 고객별 총 주문 금액 결과와 같다", "cmd": ["sh", "-c", "[ -s /tmp/q9.txt ] && [ \\"$(sort /tmp/q9.txt)\\" = \\"$(mariadb shop -e \\"SELECT c.name, SUM(o.qty * p.price) AS total FROM customers c JOIN orders o ON o.customer_id = c.id JOIN products p ON p.id = o.product_id GROUP BY c.name\\" | sort)\\" ]"]}]', '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 10, 'WHERE 와 HAVING 의 차이는?', '쿼리에서 `WHERE` 와 `HAVING` 의 차이로 알맞은 것은 무엇일까요?', '"묶기" 전과 후를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["`WHERE` 는 묶은 뒤의 집계 결과를 거르고, `HAVING` 은 묶기 전의 행을 거른다", "`WHERE` 는 묶기 전의 행을 거르고, `HAVING` 은 묶은 뒤의 집계 결과를 거른다", "둘은 이름만 다르고 항상 똑같이 동작해서 바꿔 써도 된다", "`WHERE` 는 SELECT 에서만, `HAVING` 은 INSERT 에서만 쓸 수 있다"]', 1, '`WHERE` 는 `GROUP BY` 로 묶기 **전** 의 개별 행을 거르고, `HAVING` 은 묶은 **뒤** 의 집계 결과(`COUNT(*) >= 2` 처럼)를 거릅니다. 집계 함수 조건은 보통 `WHERE` 에 쓸 수 없고 `HAVING` 에 씁니다.', NULL, NULL, NULL, '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 11, '가장 비싼 상품 하나', '`products` 에서 **가장 비싼 상품 하나** 의 이름을 구하는 쿼리입니다. 빈칸을 채우세요.', '큰 값부터 정렬해야 맨 위가 가장 비쌉니다.', NULL, NULL, '[]', 'fill', '["DESC", "ASC", "MAX", "TOP"]', NULL, '`ORDER BY price DESC` 는 큰 값부터 정렬하므로 `LIMIT 1` 이 가장 비싼 상품 하나를 남깁니다. `ASC`(작은 값부터)면 가장 싼 상품이 됩니다. `MAX`·`TOP` 은 이 자리에 쓰는 정렬 방향이 아닙니다.', '[0]', 'SELECT name FROM products ORDER BY price {0} LIMIT 1', NULL, '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 366, 12, 'SELECT 문 절을 쓰는 순서', '도시별 고객 수를 세어 많은 순으로 상위 2개를 뽑는 쿼리의 **절** 입니다. SQL 에서 절을 쓰는 순서에 맞게 놓아 보세요.', '고르기 → 테이블 → 행 거르기 → 묶기 → 정렬 → 개수 순서예요.', NULL, NULL, '[]', 'order', '["`SELECT city, COUNT(*) AS cnt`", "`FROM customers`", "`WHERE id > 1`", "`GROUP BY city`", "`ORDER BY cnt DESC`", "`LIMIT 2`"]', NULL, 'SELECT 문의 절은 `SELECT` → `FROM` → `WHERE` → `GROUP BY` → (`HAVING`) → `ORDER BY` → `LIMIT` 순서로 씁니다.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "MariaDB SELECT", "url": "https://mariadb.com/kb/en/select/"}, {"title": "MariaDB WHERE", "url": "https://mariadb.com/kb/en/where/"}, {"title": "MariaDB ORDER BY", "url": "https://mariadb.com/kb/en/order-by/"}, {"title": "MariaDB GROUP BY", "url": "https://mariadb.com/kb/en/group-by/"}, {"title": "MariaDB JOIN 소개", "url": "https://mariadb.com/kb/en/joins-introduction/"}, {"title": "MariaDB LEFT JOIN", "url": "https://mariadb.com/kb/en/left-join/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 366 AND order_index = 12);

